class Solution {
  public String smallestGoodBase(String n) {
    long num = Long.parseLong(n);
    // try the longest representations (all ones) first: num = 1 + k + ... + k^m
    for (int m = 63 - Long.numberOfLeadingZeros(num); m >= 2; m--) {
      long k = (long) Math.pow(num, 1.0 / m);
      if (k < 2) continue;
      long sum = 1, term = 1;
      for (int i = 0; i < m; i++) {
        term *= k;
        sum += term;
      }
      if (sum == num) return String.valueOf(k);
    }
    return String.valueOf(num - 1);
  }
}
